-- ════════════════════════════════════════════════════════════════════════════════════
-- Nightly run: raw member → trigger → care-plan need → action → worklist
-- Run every night after 03_load.sql (and after POST /campaigns refreshes campaign_member).
-- Each statement is safe to re-run on the same day (G9: done/declined needs are never reopened early).
-- Generated by tools/gen_sql.py: the trigger and alert conditions come from rules/rule_condition.csv.
-- ════════════════════════════════════════════════════════════════════════════════════
USE ccl;

-- ── Step 1 · Who is in which campaign (owner = the highest-priority live campaign, G3) ──
-- campaign_member itself is refreshed by the API for each Live campaign:
--   DELETE FROM campaign_member WHERE campaign_id = ?;
--   INSERT INTO campaign_member (member_id, campaign_id, holdout, added_on)
--   SELECT m.member_id, ?, CASE WHEN CRC32(CONCAT(?, ':', m.member_id)) % 100 < ? THEN 1 ELSE 0 END, rc.run_date
--   FROM member m JOIN run_config rc WHERE <campaign.where_sql>;
TRUNCATE TABLE work_member;
INSERT INTO work_member (member_id, owner_campaign, owner_priority, trigger_mode, trigger_list)
SELECT member_id, campaign_id, priority, trigger_mode, trigger_list
FROM (
  SELECT cm.member_id, c.campaign_id, c.priority, c.trigger_mode, c.trigger_list,
         ROW_NUMBER() OVER (PARTITION BY cm.member_id ORDER BY c.priority, c.campaign_id) AS rn
  FROM campaign_member cm
  JOIN campaign c ON c.campaign_id = cm.campaign_id AND c.status = 'Live'
  JOIN member m ON m.member_id = cm.member_id
  WHERE cm.holdout = 0                       -- the 10% control group gets nothing
    AND m.consent <> 'declined'              -- G2: declined consent = no further contact
    AND COALESCE(m.excluded, 0) = 0          -- G1c: extract exclusions (cancer, palliative, dialysis …)
) x
WHERE rn = 1;

-- ── Step 2 · Raw member → trigger (rule_condition; rule_trigger.use_variant picks extract flag or rulebook thresholds) ──
DELETE FROM member_signal WHERE run_date = (SELECT run_date FROM run_config WHERE id = 1);
INSERT INTO member_signal (member_id, trigger_code, state, evidence, run_date)
-- Trig3 · Hypoglycaemia · fires when: Any event in 12 months
SELECT m.member_id, 'Trig3', 'fired', CONCAT_WS('; ', CONCAT('flag_dm_hypoglycaemia_l12m ', COALESCE(CAST(m.flag_dm_hypoglycaemia_l12m AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig3'
WHERE ((t.use_variant = 'extract' AND ((m.trig3_hypoglycemia_tx = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND m.flag_dm_hypoglycaemia_l12m = 1))))
UNION ALL
-- BPU · BP urgent · fires when: BP ≥ 180/110
SELECT m.member_id, 'BPU', 'fired', CONCAT_WS('; ', CONCAT('Last_SystolicPressure_Value ', COALESCE(CAST(m.last_systolicpressure_value AS CHAR), 'none')), CONCAT('Last_DiastolicPressure_Value ', COALESCE(CAST(m.last_diastolicpressure_value AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'BPU'
WHERE ((t.use_variant = 'rulebook' AND ((m.last_systolicpressure_value >= 180)
       OR (m.last_diastolicpressure_value >= 110))))
UNION ALL
-- Trig4 · Post-discharge care · fires when: Discharge in the last 14 days, or 2 or more ED visits in 90 days
SELECT m.member_id, 'Trig4', 'fired', CONCAT_WS('; ', CONCAT('last_ip_discharge_date ', COALESCE(CAST(m.last_ip_discharge_date AS CHAR), 'none')), CONCAT('ed_visits_l12m ', COALESCE(CAST(m.ed_visits_l12m AS CHAR), 'none')), CONCAT('last_ed_visit_date ', COALESCE(CAST(m.last_ed_visit_date AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig4'
WHERE ((t.use_variant = 'extract' AND ((m.trig4_post_discharge_care = 1)))
    OR (t.use_variant = 'rulebook' AND ((DATEDIFF(rc.as_of, m.last_ip_discharge_date) <= 14)
       OR (m.ed_visits_l12m >= 2 AND DATEDIFF(rc.as_of, m.last_ed_visit_date) <= 90))))
UNION ALL
-- Trig1 · HbA1c above target · fires when: Last value ≥ individual goal (around 8%)
SELECT m.member_id, 'Trig1', 'fired', CONCAT_WS('; ', CONCAT('Last_HbA1c_Value ', COALESCE(CAST(m.last_hba1c_value AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig1'
WHERE ((t.use_variant = 'extract' AND ((m.trig1_hba1c_above_target = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND m.last_hba1c_value >= 8))))
UNION ALL
-- Trig2 · BP treatment review · fires when: ≥ 130/80 (DM or CKD) or ≥ 140/90
SELECT m.member_id, 'Trig2', 'fired', CONCAT_WS('; ', CONCAT('Last_SystolicPressure_Value ', COALESCE(CAST(m.last_systolicpressure_value AS CHAR), 'none')), CONCAT('Last_DiastolicPressure_Value ', COALESCE(CAST(m.last_diastolicpressure_value AS CHAR), 'none')), CONCAT('flag_ckd ', COALESCE(CAST(m.flag_ckd AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig2'
WHERE ((t.use_variant = 'extract' AND ((m.trig2_htn_tx_review = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_htn_l12m = 1 AND m.last_systolicpressure_value >= 140)
       OR (m.cohort_htn_l12m = 1 AND m.last_diastolicpressure_value >= 90)
       OR (m.cohort_htn_l12m = 1 AND m.cohort_t2d_l12m = 1 AND m.last_systolicpressure_value >= 130)
       OR (m.cohort_htn_l12m = 1 AND m.cohort_t2d_l12m = 1 AND m.last_diastolicpressure_value >= 80)
       OR (m.cohort_htn_l12m = 1 AND m.flag_ckd = 1 AND m.last_systolicpressure_value >= 130)
       OR (m.cohort_htn_l12m = 1 AND m.flag_ckd = 1 AND m.last_diastolicpressure_value >= 80))))
UNION ALL
-- Trig2 · cannot tell (a needed value is missing: ask the nurse once, G8)
SELECT m.member_id, 'Trig2', 'cannot_tell', 'No usable BP reading (missing or a placeholder)', rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig2'
WHERE ((m.cohort_htn_l12m = 1 AND m.last_systolicpressure_value IS NULL))
  AND NOT ((t.use_variant = 'extract' AND ((m.trig2_htn_tx_review = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_htn_l12m = 1 AND m.last_systolicpressure_value >= 140)
       OR (m.cohort_htn_l12m = 1 AND m.last_diastolicpressure_value >= 90)
       OR (m.cohort_htn_l12m = 1 AND m.cohort_t2d_l12m = 1 AND m.last_systolicpressure_value >= 130)
       OR (m.cohort_htn_l12m = 1 AND m.cohort_t2d_l12m = 1 AND m.last_diastolicpressure_value >= 80)
       OR (m.cohort_htn_l12m = 1 AND m.flag_ckd = 1 AND m.last_systolicpressure_value >= 130)
       OR (m.cohort_htn_l12m = 1 AND m.flag_ckd = 1 AND m.last_diastolicpressure_value >= 80))))
UNION ALL
-- Trig5 · Kidney check · fires when: eGFR < 60, or no eGFR/UACR in 12 months
SELECT m.member_id, 'Trig5', 'fired', CONCAT_WS('; ', CONCAT('Last_eGFR_Value ', COALESCE(CAST(m.last_egfr_value AS CHAR), 'none')), CONCAT('last_egfr_test_date ', COALESCE(CAST(m.last_egfr_test_date AS CHAR), 'none')), CONCAT('last_urine_albumin_date ', COALESCE(CAST(m.last_urine_albumin_date AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig5'
WHERE ((t.use_variant = 'extract' AND ((m.trig5_kidney_check = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.last_egfr_value < 60)
       OR (m.cohort_t2d_l12m = 1 AND (m.last_egfr_test_date IS NULL OR DATEDIFF(rc.as_of, m.last_egfr_test_date) > 365))
       OR (m.cohort_t2d_l12m = 1 AND (m.last_urine_albumin_date IS NULL OR DATEDIFF(rc.as_of, m.last_urine_albumin_date) > 365)))))
UNION ALL
-- Trig5 · cannot tell (a needed value is missing: ask the nurse once, G8)
SELECT m.member_id, 'Trig5', 'cannot_tell', 'No eGFR or UACR result', rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig5'
WHERE ((m.cohort_t2d_l12m = 1 AND m.last_egfr_value IS NULL AND m.last_uacr_value IS NULL))
  AND NOT ((t.use_variant = 'extract' AND ((m.trig5_kidney_check = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.last_egfr_value < 60)
       OR (m.cohort_t2d_l12m = 1 AND (m.last_egfr_test_date IS NULL OR DATEDIFF(rc.as_of, m.last_egfr_test_date) > 365))
       OR (m.cohort_t2d_l12m = 1 AND (m.last_urine_albumin_date IS NULL OR DATEDIFF(rc.as_of, m.last_urine_albumin_date) > 365)))))
UNION ALL
-- Trig9 · Medication adherence · fires when: PDC < 80% over 180 days, or a gap of more than 30 days
SELECT m.member_id, 'Trig9', 'fired', CONCAT_WS('; ', CONCAT('pdc_any_t2d_noninsulin ', COALESCE(CAST(m.pdc_any_t2d_noninsulin AS CHAR), 'none')), CONCAT('pdc_any_htn ', COALESCE(CAST(m.pdc_any_htn AS CHAR), 'none')), CONCAT('days_since_t2d_supply_ran_out ', COALESCE(CAST(m.days_since_t2d_supply_ran_out AS CHAR), 'none')), CONCAT('days_since_htn_supply_ran_out ', COALESCE(CAST(m.days_since_htn_supply_ran_out AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig9'
WHERE ((t.use_variant = 'extract' AND ((m.trig9_medication_adherence = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.pdc_any_t2d_noninsulin < 0.8)
       OR (m.pdc_any_htn < 0.8)
       OR (m.days_since_t2d_supply_ran_out > 30)
       OR (m.days_since_htn_supply_ran_out > 30))))
UNION ALL
-- Trig6 · HbA1c test due · fires when: > 6 months (or > 3 months if off target)
SELECT m.member_id, 'Trig6', 'fired', CONCAT_WS('; ', CONCAT('last_hba1c_date2 ', COALESCE(CAST(m.last_hba1c_date2 AS CHAR), 'none')), CONCAT('Last_HbA1c_Value ', COALESCE(CAST(m.last_hba1c_value AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig6'
WHERE ((t.use_variant = 'extract' AND ((m.trig6_hba1c_due = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND (m.last_hba1c_date2 IS NULL OR DATEDIFF(rc.as_of, m.last_hba1c_date2) > 180))
       OR (m.cohort_t2d_l12m = 1 AND m.last_hba1c_value >= 8 AND (m.last_hba1c_date2 IS NULL OR DATEDIFF(rc.as_of, m.last_hba1c_date2) > 90)))))
UNION ALL
-- Trig6 · cannot tell (a needed value is missing: ask the nurse once, G8)
SELECT m.member_id, 'Trig6', 'cannot_tell', 'No usable HbA1c result', rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig6'
WHERE ((m.cohort_t2d_l12m = 1 AND m.last_hba1c_value IS NULL))
  AND NOT ((t.use_variant = 'extract' AND ((m.trig6_hba1c_due = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND (m.last_hba1c_date2 IS NULL OR DATEDIFF(rc.as_of, m.last_hba1c_date2) > 180))
       OR (m.cohort_t2d_l12m = 1 AND m.last_hba1c_value >= 8 AND (m.last_hba1c_date2 IS NULL OR DATEDIFF(rc.as_of, m.last_hba1c_date2) > 90)))))
UNION ALL
-- Trig12 · Eye exam due · fires when: None in 24 months
SELECT m.member_id, 'Trig12', 'fired', CONCAT_WS('; ', CONCAT('last_retinal_screen_date ', COALESCE(CAST(m.last_retinal_screen_date AS CHAR), 'none')), CONCAT('last_ophthalmology_visit ', COALESCE(CAST(m.last_ophthalmology_visit AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig12'
WHERE ((t.use_variant = 'extract' AND ((m.trig12_eyeexam_due = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND (m.last_retinal_screen_date IS NULL OR DATEDIFF(rc.as_of, m.last_retinal_screen_date) > 730) AND (m.last_ophthalmology_visit IS NULL OR DATEDIFF(rc.as_of, m.last_ophthalmology_visit) > 730)))))
UNION ALL
-- Trig13 · High-risk foot · fires when: No exam in 12 months, or a high-risk code
SELECT m.member_id, 'Trig13', 'fired', CONCAT_WS('; ', CONCAT('last_foot_exam ', COALESCE(CAST(m.last_foot_exam AS CHAR), 'none')), CONCAT('flag_dm_foot_ulcer_l12m ', COALESCE(CAST(m.flag_dm_foot_ulcer_l12m AS CHAR), 'none')), CONCAT('flag_amputation ', COALESCE(CAST(m.flag_amputation AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig13'
WHERE ((t.use_variant = 'extract' AND ((m.trig13_highriskfoot_monitor = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND (m.last_foot_exam IS NULL OR DATEDIFF(rc.as_of, m.last_foot_exam) > 365))
       OR (m.cohort_t2d_l12m = 1 AND m.flag_dm_foot_ulcer_l12m = 1)
       OR (m.cohort_t2d_l12m = 1 AND m.flag_amputation = 1))))
UNION ALL
-- Trig7 · Potassium due · fires when: On an RAAS inhibitor or diuretic with no K+ in 12 months
SELECT m.member_id, 'Trig7', 'fired', CONCAT_WS('; ', CONCAT('flag_active_ACEinhibitor ', COALESCE(CAST(m.flag_active_aceinhibitor AS CHAR), 'none')), CONCAT('last_potassium_date ', COALESCE(CAST(m.last_potassium_date AS CHAR), 'none')), CONCAT('flag_active_ARBinhibitor ', COALESCE(CAST(m.flag_active_arbinhibitor AS CHAR), 'none')), CONCAT('pdc_mra ', COALESCE(CAST(m.pdc_mra AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig7'
WHERE ((t.use_variant = 'extract' AND ((m.trig7_renal_potassium_due = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_htn_l12m = 1 AND m.flag_active_aceinhibitor = 1 AND (m.last_potassium_date IS NULL OR DATEDIFF(rc.as_of, m.last_potassium_date) > 365))
       OR (m.cohort_htn_l12m = 1 AND m.flag_active_arbinhibitor = 1 AND (m.last_potassium_date IS NULL OR DATEDIFF(rc.as_of, m.last_potassium_date) > 365))
       OR (m.cohort_htn_l12m = 1 AND m.pdc_mra IS NOT NULL AND (m.last_potassium_date IS NULL OR DATEDIFF(rc.as_of, m.last_potassium_date) > 365))
       OR (m.cohort_htn_l12m = 1 AND m.pdc_thiazide IS NOT NULL AND (m.last_potassium_date IS NULL OR DATEDIFF(rc.as_of, m.last_potassium_date) > 365)))))
UNION ALL
-- Trig11 · Annual labs · fires when: None in 12 months
SELECT m.member_id, 'Trig11', 'fired', CONCAT_WS('; ', CONCAT('last_lipid_panel_date ', COALESCE(CAST(m.last_lipid_panel_date AS CHAR), 'none')), CONCAT('last_renal_panel_date ', COALESCE(CAST(m.last_renal_panel_date AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig11'
WHERE ((t.use_variant = 'extract' AND ((m.trig11_annual_labs_due = 1)))
    OR (t.use_variant = 'rulebook' AND (((m.last_lipid_panel_date IS NULL OR DATEDIFF(rc.as_of, m.last_lipid_panel_date) > 365))
       OR ((m.last_renal_panel_date IS NULL OR DATEDIFF(rc.as_of, m.last_renal_panel_date) > 365)))))
UNION ALL
-- Trig10 · New diagnosis · fires when: First code in the last 90 days
SELECT m.member_id, 'Trig10', 'fired', CONCAT_WS('; ', CONCAT('first_e11_date ', COALESCE(CAST(m.first_e11_date AS CHAR), 'none')), CONCAT('first_htn_date ', COALESCE(CAST(m.first_htn_date AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig10'
WHERE ((t.use_variant = 'extract' AND ((m.trig10_new_diagnosis = 1)))
    OR (t.use_variant = 'rulebook' AND ((DATEDIFF(rc.as_of, m.first_e11_date) <= 90)
       OR (DATEDIFF(rc.as_of, m.first_htn_date) <= 90))))
UNION ALL
-- Trig8 · Nutrition and education · fires when: None in 12 months
SELECT m.member_id, 'Trig8', 'fired', CONCAT_WS('; ', CONCAT('last_dietitian_visit ', COALESCE(CAST(m.last_dietitian_visit AS CHAR), 'none')), CONCAT('last_diabeducator_visit ', COALESCE(CAST(m.last_diabeducator_visit AS CHAR), 'none'))), rc.run_date
FROM member m JOIN run_config rc JOIN rule_trigger t ON t.trigger_code = 'Trig8'
WHERE ((t.use_variant = 'extract' AND ((m.trig8_nutrition_due = 1)))
    OR (t.use_variant = 'rulebook' AND ((m.cohort_t2d_l12m = 1 AND (m.last_dietitian_visit IS NULL OR DATEDIFF(rc.as_of, m.last_dietitian_visit) > 365) AND (m.last_diabeducator_visit IS NULL OR DATEDIFF(rc.as_of, m.last_diabeducator_visit) > 365)))));


-- ── Step 3 · Score: R = C + M + K + U + A, tier, alert colour, contact priority (rulebook §2, §4) ──
UPDATE member m JOIN run_config rc
SET m.r_total = COALESCE(m.clinical_score, 0) + COALESCE(m.comorbid_complication_score, 0) + COALESCE(m.kidney_score, 0)
              + COALESCE(m.utilization_score, 0) + COALESCE(m.age_sex_score, 0),
    m.scored_on = rc.run_date;
UPDATE member m JOIN rule_tier t ON m.r_total BETWEEN t.r_min AND t.r_max SET m.tier = t.tier;

INSERT INTO work_member (member_id, n_fired, has_trig4)
SELECT s.member_id, SUM(s.state = 'fired'), MAX(s.trigger_code = 'Trig4' AND s.state = 'fired')
FROM member_signal s JOIN run_config rc ON s.run_date = rc.run_date
GROUP BY s.member_id
ON DUPLICATE KEY UPDATE n_fired = VALUES(n_fired), has_trig4 = VALUES(has_trig4);

UPDATE member m JOIN run_config rc LEFT JOIN work_member w ON w.member_id = m.member_id
SET m.alert = CASE
    WHEN ((m.priority_clinical_review = 1)
       OR (m.flag_dka_l12m = 1)
       OR (m.flag_dm_hypoglycaemia_l12m = 1)
       OR (m.last_systolicpressure_value >= 180)
       OR (m.last_diastolicpressure_value >= 110)
       OR (m.last_egfr_value < 15)) THEN 'RED'
    WHEN ((m.trig4_post_discharge_care = 1)
       OR (m.last_hba1c_value >= 9)
       OR (m.last_systolicpressure_value >= 160)
       OR (m.last_diastolicpressure_value >= 100)
       OR (m.pdc_any_t2d_noninsulin < 0.5)
       OR (m.pdc_any_htn < 0.5)) THEN 'AMBER'
    WHEN COALESCE(w.n_fired, 0) > 0 THEN 'YELLOW'     -- off target or an overdue test
    ELSE 'GREEN' END;

-- contact priority: first matching row of rule_priority (e.g. AMBER + post-discharge = P1)
INSERT INTO work_member (member_id, match_order)
SELECT m.member_id, MIN(p.match_order)
FROM member m
JOIN rule_priority p ON p.alert = m.alert
LEFT JOIN work_member w ON w.member_id = m.member_id
WHERE p.needs_trigger = '' OR (p.needs_trigger = 'Trig4' AND COALESCE(w.has_trig4, 0) = 1)
GROUP BY m.member_id
ON DUPLICATE KEY UPDATE match_order = VALUES(match_order);
UPDATE member m JOIN work_member w ON w.member_id = m.member_id JOIN rule_priority p ON p.match_order = w.match_order
SET m.contact_priority = p.priority;

-- ── Step 4 · Trigger → care-plan need (only campaign members; business-mode campaigns keep only their listed triggers) ──
-- 4a. a declined need comes back only after its 90-day hold (G4)
UPDATE care_plan_need n
JOIN run_config rc
JOIN member_signal s ON s.member_id = n.member_id AND s.trigger_code = n.trigger_code AND s.run_date = rc.run_date AND s.state = 'fired'
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
SET n.status = 'open', n.gap_state = 'Potential', n.hold_until = NULL, n.closed_on = NULL,
    n.due_date = DATE_ADD(rc.run_date, INTERVAL t.due_days DAY)
WHERE n.status = 'declined' AND n.hold_until <= rc.run_date;

-- 4b. new needs (existing ones keep their status: G9)
INSERT INTO care_plan_need (member_id, trigger_code, dm_module, class, class_order, trigger_order, slot, status, gap_state, due_date, evidence, opened_on)
SELECT s.member_id, s.trigger_code, t.dm_module, t.class, t.class_order, t.trigger_order, 'FUTURE', 'open', 'Potential',
       DATE_ADD(rc.run_date, INTERVAL t.due_days DAY), s.evidence, rc.run_date
FROM member_signal s
JOIN run_config rc ON s.run_date = rc.run_date
JOIN rule_trigger t ON t.trigger_code = s.trigger_code
JOIN work_member w ON w.member_id = s.member_id AND w.owner_campaign IS NOT NULL
WHERE s.state = 'fired'
  AND (w.trigger_mode = 'all' OR CONCAT(',', w.trigger_list, ',') LIKE CONCAT('%,', s.trigger_code, ',%'))
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- 4c. a need whose trigger stopped firing was met in claims → Closed (the only way a gap closes)
UPDATE care_plan_need n
JOIN run_config rc
JOIN work_member w ON w.member_id = n.member_id AND w.owner_campaign IS NOT NULL
LEFT JOIN member_signal s ON s.member_id = n.member_id AND s.trigger_code = n.trigger_code AND s.run_date = rc.run_date AND s.state = 'fired'
SET n.status = 'done', n.slot = 'CLOSED', n.gap_state = 'Closed', n.closed_on = COALESCE(n.closed_on, rc.run_date)
WHERE s.member_id IS NULL AND (n.status = 'open' OR n.gap_state = 'Reported');
UPDATE action a JOIN care_plan_need n ON n.member_id = a.member_id AND n.trigger_code = a.trigger_code
SET a.status = 'done', a.closed_at = NOW()
WHERE a.kind IN ('care_plan', 'follow_up') AND a.status = 'open' AND n.gap_state = 'Closed';   -- the claim did the verifying

-- ── Step 5 · Slots: CURRENT = top 3 by class order (safety → acute → uncontrolled → barrier → gap → goal), NEXT = 4–6 ──
TRUNCATE TABLE work_rank;
INSERT INTO work_rank (member_id, trigger_code, rn)
SELECT member_id, trigger_code, ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY class_order, trigger_order)
FROM care_plan_need WHERE status = 'open';
UPDATE care_plan_need n JOIN work_rank r ON r.member_id = n.member_id AND r.trigger_code = n.trigger_code
SET n.slot = CASE WHEN r.rn <= 3 THEN 'CURRENT' WHEN r.rn <= 6 THEN 'NEXT' ELSE 'FUTURE' END;
UPDATE care_plan_need SET slot = 'CLOSED' WHERE status <> 'open';

-- ── Step 6 · Need → action: exactly one open care-plan action per CURRENT need (G7) ──
INSERT INTO action (member_id, trigger_code, kind, title, channel, owner_role, due_date, status, created_by, created_at)
SELECT n.member_id, n.trigger_code, 'care_plan', t.action_title, t.channel, t.owner_role, n.due_date, 'open', 'nightly', NOW()
FROM care_plan_need n
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
LEFT JOIN action a ON a.member_id = n.member_id AND a.trigger_code = n.trigger_code AND a.kind IN ('care_plan', 'follow_up') AND a.status = 'open'
WHERE n.slot = 'CURRENT' AND n.status = 'open' AND a.action_id IS NULL;   -- an open follow-up on the need counts as its action

-- ── Step 7 · The nudge: one contact per member — a call by SLA (P1 today, P2 next day, P3 in 3 days) or a digital nudge (P4) ──
INSERT INTO work_member (member_id, has_open_contact)
SELECT member_id, 1 FROM action
WHERE status = 'open' AND kind IN ('nudge', 'call', 'follow_up', 'retry', 'escalation')
GROUP BY member_id
ON DUPLICATE KEY UPDATE has_open_contact = 1;
INSERT INTO work_member (member_id, reached_14d)       -- G3: no new outreach within 14 days of a reached call
SELECT o.member_id, 1 FROM outcome o JOIN run_config rc
WHERE o.reached = 1 AND o.recorded_at >= DATE_SUB(rc.run_date, INTERVAL 14 DAY)
GROUP BY o.member_id
ON DUPLICATE KEY UPDATE reached_14d = 1;
INSERT INTO work_member (member_id, top_need)
SELECT n.member_id, t.name
FROM care_plan_need n JOIN work_rank r ON r.member_id = n.member_id AND r.trigger_code = n.trigger_code AND r.rn = 1
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
ON DUPLICATE KEY UPDATE top_need = VALUES(top_need);

INSERT INTO action (member_id, kind, title, channel, owner_role, due_date, status, created_by, created_at)
SELECT m.member_id,
       CASE WHEN p.sla_days IS NULL THEN 'nudge' ELSE 'call' END,
       CASE WHEN p.sla_days IS NULL THEN CONCAT('Digital nudge: ', w.top_need) ELSE CONCAT(m.contact_priority, ' call: ', w.top_need) END,
       p.channel, 'Nurse',
       DATE_ADD(rc.run_date, INTERVAL COALESCE(p.sla_days, 2) DAY), 'open', 'nightly', NOW()
FROM member m
JOIN run_config rc
JOIN work_member w ON w.member_id = m.member_id AND w.owner_campaign IS NOT NULL AND w.top_need IS NOT NULL
JOIN rule_priority p ON p.priority = m.contact_priority AND p.alert = m.alert
WHERE COALESCE(w.has_open_contact, 0) = 0 AND COALESCE(w.reached_14d, 0) = 0;

-- ── Step 8 · Worklist orchestration (rulebook §4) ──
-- Order: safety or RED first → tier 4…1 → campaign priority → most overdue. One row per member, led by
-- their most urgent open nurse action. Nurses are matched by language, round-robin, within daily capacity;
-- anything over capacity is 'queued' and rolls to the next day.
TRUNCATE TABLE worklist;
INSERT INTO worklist (work_date, member_id, nurse_id, rank_no, nurse_rank, action_id, priority, alert, tier, reason, due_by, status)
SELECT z.run_date, z.member_id, z.nurse_id, z.rank_no, z.nurse_rank, z.action_id, z.contact_priority, z.alert, z.tier, z.title, z.due_date,
       CASE WHEN z.nurse_rank <= z.daily_capacity THEN 'today' ELSE 'queued' END
FROM (
  SELECT rc.run_date, q.*, nl.nurse_id, nu.daily_capacity,
         ROW_NUMBER() OVER (PARTITION BY nl.nurse_id ORDER BY q.rank_no) AS nurse_rank      -- capacity counts across all of a nurse's languages
  FROM (
    SELECT l.*,
           ROW_NUMBER() OVER (ORDER BY l.urgent DESC, l.tier DESC, l.owner_priority, l.due_date, l.r_total DESC, l.member_id) AS rank_no,
           ROW_NUMBER() OVER (PARTITION BY l.lang ORDER BY l.urgent DESC, l.tier DESC, l.owner_priority, l.due_date, l.r_total DESC, l.member_id) AS lang_rn
    FROM (
      SELECT a.member_id, a.action_id, a.title, a.due_date, m.contact_priority, m.alert, m.tier, m.r_total, w.owner_priority,
             CASE WHEN m.alert = 'RED' OR m.priority_clinical_review = 1 THEN 1 ELSE 0 END AS urgent,
             CASE WHEN m.language IN (SELECT language FROM nurse_language) THEN m.language ELSE 'English' END AS lang,
             ROW_NUMBER() OVER (PARTITION BY a.member_id
                                ORDER BY CASE a.kind WHEN 'call' THEN 1 WHEN 'retry' THEN 2 ELSE 3 END, a.due_date) AS lead_rn
      FROM action a
      JOIN member m ON m.member_id = a.member_id
      JOIN work_member w ON w.member_id = a.member_id
      WHERE a.status = 'open' AND a.kind IN ('call', 'follow_up', 'retry')   -- escalations go to the clinical lead, not the nurse list
    ) l
    WHERE l.lead_rn = 1
  ) q
  JOIN run_config rc
  JOIN (SELECT language, COUNT(*) AS n_nurses FROM nurse_language GROUP BY language) lc ON lc.language = q.lang
  JOIN nurse_language nl ON nl.language = q.lang AND nl.lang_idx = MOD(q.lang_rn - 1, lc.n_nurses) + 1   -- language first, then round-robin
  JOIN nurse nu ON nu.nurse_id = nl.nurse_id
) z;

-- the member's open actions go to the nurse who has them on the list
UPDATE action a JOIN worklist w ON w.member_id = a.member_id
SET a.assignee = w.nurse_id
WHERE a.status = 'open' AND a.assignee IS NULL;
